import json, re
import pandas as pd
import pdfplumber
from difflib import SequenceMatcher

vendors = pd.read_excel('/root/vendors.xlsx', dtype={'id': str, 'name': str, 'iban': str})
pos = pd.read_csv('/root/purchase_orders.csv', dtype={'po_number': str, 'vendor_id': str})

# Normalize vendor names for matching
_abbrev = {
    'limited': 'ltd',
    'ltd.': 'ltd',
    'corporation': 'corp',
    'incorporated': 'inc',
    'company': 'co',
}

def normalize_name(text: str) -> str:
    text = text.lower()
    text = re.sub(r'[^a-z0-9\s]', ' ', text)
    text = ' '.join(text.split())
    for k, v in _abbrev.items():
        text = text.replace(k, v)
    return text

def normalize_iban(text: str) -> str:
    return re.sub(r'\s+', '', text or '').upper()

vendor_records = []
name_to_vendor = {}
for _, row in vendors.iterrows():
    name = str(row['name'])
    norm = normalize_name(name)
    vendor_records.append((norm, row['id'], name, row['iban']))
    # If duplicates, keep first; fuzzy will still find best
    name_to_vendor.setdefault(norm, (row['id'], name, row['iban']))

# Build PO map
po_map = {}
for _, row in pos.iterrows():
    po_map[str(row['po_number'])] = {
        'vendor_id': str(row['vendor_id']),
        'amount': float(row['amount'])
    }


def best_vendor_match(vendor_name: str):
    if not vendor_name:
        return None
    norm = normalize_name(vendor_name)
    if norm in name_to_vendor:
        return name_to_vendor[norm]
    # Fuzzy match
    best = None
    best_score = 0.0
    for norm_name, vid, cname, iban in vendor_records:
        score = SequenceMatcher(None, norm, norm_name).ratio()
        if score > best_score:
            best_score = score
            best = (vid, cname, iban)
    if best_score >= 0.85:
        return best
    return None


def parse_invoice(text: str):
    vendor_name = None
    amount = None
    iban = None
    po_number = None
    for line in (text or '').splitlines():
        line = line.strip()
        if line.startswith('From:'):
            vendor_name = line.split('From:', 1)[1].strip()
        elif line.startswith('Total'):
            m = re.search(r'\$([0-9,]+(?:\.\d{2})?)', line)
            if m:
                amount = float(m.group(1).replace(',', ''))
        elif line.startswith('Payment IBAN:'):
            iban = line.split('Payment IBAN:', 1)[1].strip()
        elif line.startswith('PO Number:'):
            po_number = line.split('PO Number:', 1)[1].strip()
            if po_number in ('', 'N/A', 'None'):
                po_number = None
    return vendor_name, amount, iban, po_number

report = []

with pdfplumber.open('/root/invoices.pdf') as pdf:
    for idx, page in enumerate(pdf.pages, start=1):
        text = page.extract_text()
        vendor_name, amount, iban, po_number = parse_invoice(text)
        match = best_vendor_match(vendor_name)
        reason = None
        if match is None:
            reason = 'Unknown Vendor'
        else:
            vendor_id, canon_name, vendor_iban = match
            if normalize_iban(iban) != normalize_iban(vendor_iban):
                reason = 'IBAN Mismatch'
            else:
                if not po_number or po_number not in po_map:
                    reason = 'Invalid PO'
                else:
                    po = po_map[po_number]
                    if abs(po['amount'] - float(amount)) > 0.01:
                        reason = 'Amount Mismatch'
                    elif po['vendor_id'] != vendor_id:
                        reason = 'Vendor Mismatch'
        if reason:
            report.append({
                'invoice_page_number': idx,
                'vendor_name': vendor_name,
                'invoice_amount': float(amount) if amount is not None else None,
                'iban': iban,
                'po_number': po_number if po_number else None,
                'reason': reason,
            })

with open('/root/fraud_report.json', 'w') as f:
    json.dump(report, f, indent=2)

print('flagged', len(report))
